    quiz: [['Which command lets the switch check usernames for remote logins?', ['login', 'login local', 'password', 'transport input ssh'], 1, 'login local uses the username database in the configuration.'], ['What is required before generating RSA keys?', ['An enable password', 'A hostname and a domain name', 'A VLAN 10', 'A default route'], 1, 'The key is named hostname.domain-name.'], ['Why prefer SSH to Telnet?', ['It is faster', 'It encrypts the session', 'It uses UDP', 'It needs no password'], 1, 'Telnet sends everything, including passwords, in clear text.']],
    related: ['m12-configure-a-switch', 'm6-ssh', 'm6-telnet', 'm9-authentication'],
