    mistakes: [['PCs reach their gateway but not the other VLAN', 'ip routing is missing on MLS1.'], ['Pings to 172.16.1.1 time out', 'R1 is missing the return routes to 192.168.10.0 and 192.168.20.0.'], ['Cannot put an IP address on G0/1', 'Enter no switchport on the interface first.']],
    quiz: [['Which command lets a 3560 route between VLANs?', ['ip routing', 'router ospf', 'switchport mode trunk', 'ip default-gateway'], 0, 'ip routing enables Layer 3 forwarding.'], ['What does no switchport do?', ['Shuts the port', 'Makes it a routed port', 'Removes VLANs', 'Enables a trunk'], 1, 'It converts a switch port into a Layer 3 port.'], ['Why is a Layer 3 switch faster than router-on-a-stick for inter-VLAN traffic?', ['It uses UDP', 'Routing happens in switch hardware without sharing one uplink', 'It has no ARP', 'It uses bigger frames'], 1, 'Traffic does not need to cross a single trunk to an external router.']],
    related: ['m7-inter-vlan-routing', 'm7-static-routing', 'm7-default-routing'],
