    mistakes: [['Ping fails but the route exists on R1', 'Check the return route on R2.'], ['Backup route never appears', 'A floating route only replaces the main route when the main route is removed, for example when its interface goes down.'], ['"% Inconsistent address and mask"', 'Use 255.255.255.252 for the /30 links.']],
    quiz: [['What makes a static route "floating"?', ['A higher administrative distance than the main route', 'A lower metric', 'The keyword float', 'Being a default route'], 0, 'It stays out of the table until the better route disappears.'], ['A ping reaches the far router but no replies return. What is missing?', ['A DNS record', 'The return route', 'A VLAN', 'NAT'], 1, 'Routing must work in both directions.'], ['Which route is written 0.0.0.0 0.0.0.0?', ['Loopback route', 'Default route', 'Host route', 'Floating route'], 1, 'The default route matches every destination.']],
    related: ['m12-configure-static-routing', 'm7-static-routing', 'm7-default-routing', 'm11-routing-problems'],
