export const ptById = new Map(PT_LABS.map((l) => [l.id, l]));
/** Lessons that link to a Packet Tracer lab sheet. */
export const ptForLesson = (lessonId: string) => PT_LABS.filter((l) => l.related.includes(lessonId));
